{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 도시공원 조례상 65세 이상 입장료·운동시설 이용료 전액 자동 면제 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "입장료는 65세 이상인 사람에 대해 시장이 면제할 수 있으므로, 전액 면제가 자동으로 확정되지는 않는다. 운동시설 이용료는 65세 이상인 사람에 대해 100분의 50 범위에서 규칙이 정하는 바에 따라 감면할 수 있을 뿐, 전액 자동 면제 규정은 없다. 따라서 65세 이상이라고 해서 두 요금이 모두 자동으로 전액 면제되지는 않는다.",
          "b_ids": "도시공원:제20조제1항, 도시공원:제20조제1항제2호, 도시공원:제20조제3항, 도시공원:제20조제3항제1호"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "서울특별시 도시공원 조례상 입장료와 운동시설 이용료의 65세 이상 면제 여부 구분",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "입장료는 제20조제1항제2호에 따라 65세 이상인 사람이 면제 대상에 포함되어 시장이 면제할 수 있다. 운동시설 이용료는 제20조제3항제1호에 따라 65세 이상인 사람이 100분의 50 범위에서 규칙이 정하는 바에 따라 감면 대상일 뿐, 전액 면제가 아니다. 즉 입장료는 면제 가능 대상이고, 운동시설 이용료는 감면 가능 대상이며 두 요금은 구분된다.",
          "b_ids": "도시공원:제20조제1항, 도시공원:제20조제1항제2호, 도시공원:제20조제3항, 도시공원:제20조제3항제1호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
